type pageRoomHandlers struct{ *Server }

func (s pageRoomHandlers) GET(w http.ResponseWriter, r *http.Request) {
	sess, _, ok := s.ReadSession(w, r)
	if !ok {
		return
	}

	p := dpapp.PageRoom{
		App: s.app,
	}
	defer s.recoverPanic(w, r, nil, "PageRoom.GET")
	body, err := p.GET(r, sess)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling PageRoom.GET", err)
		return
	}
	genericHead := s.app.Head(r)

	bodyAttrs := func(w http.ResponseWriter) {
		httpserve.WriteReloadOnVisibility(w)
	}

	bodySuffix := func(w http.ResponseWriter) {

		_, _ = io.WriteString(w, ` data-init="@get('`)
		if sess.UserID() != "" {
			_, _ = io.WriteString(w, `/room/_$/',{retry:'always',retryMaxCount:Infinity})"`)
		} else {
			_, _ = io.WriteString(w, `/room/_$/anon/',{retry:'always',retryMaxCount:Infinity})"`)
		}
	}

	if err := s.writeHTML(
		w, r, http.StatusOK, sess.Token(), genericHead, nil, body, bodyAttrs, bodySuffix,
	); err != nil {
		s.LogErr("rendering PageRoom", err)
		return
	}
}

func (s pageRoomHandlers) GETStream(w http.ResponseWriter, r *http.Request) {
	if !s.CheckDatastarRequest(w, r) {
		return
	}
	sess, sessToken, ok := s.ReadSession(w, r)
	if !ok {
		return
	}

	if sess.UserID() == "" {
		// The query carries the signals a stream subscribes by,
		// which the anonymous route needs as much as this one.
		// EscapedPath, not the decoded Path: a value carrying "?" or "#" re-parses
		// in the Location header as a query or a fragment.
		target := r.URL.EscapedPath() + "anon/"
		if r.URL.RawQuery != "" {
			target += "?" + r.URL.RawQuery
		}
		http.Redirect(w, r, target, http.StatusSeeOther)
		return
	}

	var subjSignals struct {
		Room string `json:"room"`
	}
	if err := datastar.ReadSignals(r, &subjSignals); err != nil {
		s.HTTPErrBad(w, "reading signals", err)
		return
	}
	if subjSignals.Room == "" {
		s.HTTPErrBad(w, "invalid signal",
			fmt.Errorf("signal %q must not be empty", "room"))
		return
	}

	p := dpapp.PageRoom{
		App: s.app,
	}
	s.handleStreamRequest(w, r, sessToken, sess, evSubjPageRoom(sess.UserID(), subjSignals.Room),
		nil,
		nil,
		func(
			streamID datapages.StreamID,
			sse *datastar.ServerSentEventGenerator, ch <-chan messaging.Message,
		) {
			defer s.recoverPanic(w, r, sse, "PageRoom stream")
			var eventRoomSaid dpapp.EventRoomSaid
			var eventNoticed dpapp.EventNoticed
			for msg := range ch {
				switch {
				case strings.HasPrefix(msg.Subject, EvPrefixRoomSaid):
					eventRoomSaid = dpapp.EventRoomSaid{}
					if err := json.Unmarshal(msg.Data, &eventRoomSaid); err != nil {
						s.LogErr("unmarshaling EventRoomSaid JSON", err)
						continue
					}
					if err := p.OnRoomSaid(
						eventRoomSaid,
						dpsse.New(sse),
					); err != nil {
						s.LogErr("handling PageRoom.OnRoomSaid", err)
					}
				case strings.HasPrefix(msg.Subject, EvPrefixNoticed):
					eventNoticed = dpapp.EventNoticed{}
					if err := json.Unmarshal(msg.Data, &eventNoticed); err != nil {
						s.LogErr("unmarshaling EventNoticed JSON", err)
						continue
					}
					if err := p.OnNoticed(
						eventNoticed,
						dpsse.New(sse),
					); err != nil {
						s.LogErr("handling PageRoom.OnNoticed", err)
					}
				}
			}
		})
}

