type dispatcherEventRowAdded struct {
	s   *Server
	ctx context.Context
}

func (d dispatcherEventRowAdded) Dispatch(e dpapp.EventRowAdded) error {
	return d.DispatchCtx(d.ctx, e)
}

func (d dispatcherEventRowAdded) DispatchCtx(
	ctx context.Context, e dpapp.EventRowAdded,
) error {
	j, err := json.Marshal(e)
	if err != nil {
		return fmt.Errorf("marshaling EventRowAdded JSON: %w", err)
	}
	err = d.s.messageBroker.Publish(ctx, d.s.messageBrokerMetrics, EvSubjRowAdded, j)
	if err != nil {
		return fmt.Errorf("publishing subject %q: %w", EvSubjRowAdded, err)
	}
	return nil
}

type dispatcherEventRoomSaid struct {
	s   *Server
	ctx context.Context
}

func (d dispatcherEventRoomSaid) Dispatch(e dpapp.EventRoomSaid) error {
	return d.DispatchCtx(d.ctx, e)
}

func (d dispatcherEventRoomSaid) DispatchCtx(
	ctx context.Context, e dpapp.EventRoomSaid,
) error {
	if e.Room == "" {
		return errors.New("EventRoomSaid.Room must not be empty")
	}
	j, err := json.Marshal(e)
	if err != nil {
		return fmt.Errorf("marshaling EventRoomSaid JSON: %w", err)
	}
	subj := "room.said." + subject.Encode(string(e.Room))
	err = d.s.messageBroker.Publish(ctx, d.s.messageBrokerMetrics, subj, j)
	if err != nil {
		return fmt.Errorf("publishing subject %q: %w", subj, err)
	}
	return nil
}

